log_level.description:
Logging verbosity: INFO, DEBUG, WARNING, ERROR
    "enum": [
      "INFO",
      "DEBUG",
      "WARNING",
      "ERROR"
    ]
  },
  "log_file": {
    "type": "string",
    "default": "",
    "description": "Path to append log messages (default: stderr)"
  },
  "no_give_up": {
    "type": "bool",
    "default": false,
    "description": "Continue passes even after 50000 iterations without progress"
  },
  "print_diff": {
    "type": "bool",
    "default": false,
    "description": "Print changes applied by transformations"
  },
  "save_temps": {
    "type": "bool",
    "default": false,
    "description": "Preserve /tmp/cvise-* temporary directories after exit"
  },
  "skip_initial_passes": {
    "type": "bool",
    "default": false,
    "description": "Skip initial fast passes (useful for partially reduced inputs)"
  },
  "skip_interestingness_test_check": {
    "type": "bool",
    "default": false,
    "description": "Skip verifying that the interestingness test passes on the original input"
  },
  "remove_pass": {
    "type": "list",
    "default": [],
    "description": "List of pass names to exclude from the schedule (comma-separated strings are accepted as items)"
  },
  "start_with_pass": {
    "type": "string",
    "default": "",
    "description": "Initial pass to run; overrides default schedule start"
  },
  "no_timing": {
    "type": "bool",
    "default": false,
    "description": "Suppress timing info in reduction progress"
  },
  "timestamp": {
    "type": "bool",
    "default": false,
    "description": "Use absolute timestamps instead of relative time offsets"
  },
  "timeout": {
    "type": "number",
    "default": 0,
    "description": "Seconds to wait for interestingness test to complete (0 = no timeout)"
  },
  "no_cache": {
    "type": "bool",
    "default": false,
    "description": "Disable caching of pass behavior across runs"
  },
  "skip_key_off": {
    "type": "bool",
    "default": false,
    "description": "Disable skipping the rest of a pass when 's' key is pressed"
  },
  "max_improvement": {
    "type": "number",
    "default": 0,
    "description": "Maximum bytes a single transformation may remove (0 = unlimited)"
  },
  "pass_group": {
    "type": "string",
    "default": "",
    "description": "Predefined pass group: all, binary, opencl-120, delta",
    "enum": [
      "all",
      "binary",
      "opencl-120",
      "delta"
    ]
  },
  "pass_group_file": {
    "type": "string",
    "default": "",
    "description": "Path to JSON file defining a custom pass group"
  },
  "clang_delta_std": {
    "type": "string",
    "default": "",
    "description": "C++ standard for clang_delta passes: c++98, c++11, c++14, c++17, c++20, c++2b",
    "enum": [
      "c++98",
      "c++11",
      "c++14",
      "c++17",
      "c++20",
      "c++2b"
    ]
  },
  "clang_delta_preserve_routine": {
    "type": "string",
    "default": "",
    "description": "Function name to preserve in replace-function-def-with-decl clang_delta pass"
  },
  "not_c": {
    "type": "bool",
    "default": false,
    "description": "Disable C/C++-specific passes"
  },
  "renaming": {
    "type": "bool",
    "default": false,
    "description": "Enable variable/function renaming passes (disabled by default)"
  },
  "commands": {
    "type": "list",
    "default": [],
    "description": "Shell commands to run as interestingness test (instead of test executable)"
  },
  "shell": {
    "type": "string",
    "default": "",
    "description": "Shell to use for --commands (e.g., /bin/sh, /bin/bash)"
  },
  "to_utf8": {
    "type": "bool",
    "default": false,
    "description": "Convert non-UTF-8 encoded inputs to UTF-8 before processing"
  },
  "skip_after_n_transforms": {
    "type": "number",
    "default": 0,
    "description": "Skip a pass after N successful transformations (0 = unlimited)"
  },
  "stopping_threshold": {
    "type": "number",
    "default": 0.0,
    "description": "Stop reduction when file size reaches this fraction of original (between 0.0 and 1.0)"
  },
  "interestingness_test": {
    "type": "string",
    "default": "",
    "description": "Path to executable used to determine if a transformed test case is still interesting"
  },
  "test_cases": {
    "type": "list",
    "default": [],
    "description": "Input test cases to reduce"
  }},
